   330    static bool unpack_deltas (const HBUINT8 *&p /* IN/OUT */,
   331                               hb_vector_t<int> &deltas /* IN/OUT */,
   332                               const hb_bytes_t &bytes)
   333    {
   334      enum packed_delta_flag_t
   335      {
   336        DELTAS_ARE_ZERO      = 0x80,
   337        DELTAS_ARE_WORDS     = 0x40,
   338        DELTA_RUN_COUNT_MASK = 0x3F
   339      };
   340
   341      unsigned int i = 0;
   342      unsigned int count = deltas.length;
   343      while (i < count)
   344      {
   345        if (unlikely (!bytes.check_range (p))) return false;
   346        uint8_t control = *p++;
   347        unsigned int run_count = (control & DELTA_RUN_COUNT_MASK) + 1;
   348        unsigned int j;
   349        if (control & DELTAS_ARE_ZERO)
   350          for (j = 0; j < run_count && i < count; j++, i++)
   351            deltas[i] = 0;
   352        else if (control & DELTAS_ARE_WORDS)
   353          for (j = 0; j < run_count && i < count; j++, i++)
   354          {
   355            if (unlikely (!bytes.check_range ((const HBUINT16 *) p)))
   356              return false;
   357            deltas[i] = *(const HBINT16 *) p;
   358            p += HBUINT16::static_size;
   359          }
   360        else
   361          for (j = 0; j < run_count && i < count; j++, i++)
   362          {
   363            if (unlikely (!bytes.check_range (p)))
   364              return false;
   365            deltas[i] = *(const HBINT8 *) p++;
   366          }
   367        if (j < run_count)
   368          return false;
   369      }
   370      return true;
   371    }
